sections.body:
下列代码保存为 faq-select.mjs，用 node faq-select.mjs 运行。rows 是入库时已校验字段、唯一 ID 与非空答案的可信目录；hits 是检索输出。函数只演示展示前的二次校验与选择，不含模型、向量计算或网络。

```js
/**
 * @Author liliwei
 * @Date 2026-10-25
 * @LastEditors liliwei
 * @LastEditTime 2026-10-25
 * @description 从已审核 FAQ 中选择可展示条目；不执行模型推理。
 */

/**
 * @param {{id:string,score:number}[]} hits 检索候选，score 为未乘 100 的余弦分数。
 * @param {object[]} rows 已检查唯一 ID、字段和正文的可信 FAQ 目录。
 * @param {{build:string,channel:string,locale:string}} ctx 应用提供的版本上下文。
 * @param {number} minScore 开发集确定的最低分，本例仅用于演示。
 * @param {number} minGap 第一、二名的最小分差，本例仅用于演示。
 * @returns {{id:string,answer:string}|null} 审核原文或暂不推荐；不保证语义正确。
 */
function selectFaq(hits, rows, ctx, minScore, minGap) {
  const keys = ["build", "channel", "locale"];
  if (!Array.isArray(hits) || !Array.isArray(rows) ||
      !ctx || keys.some(k => typeof ctx[k] !== "string" || !ctx[k]) ||
      !Number.isFinite(minScore) || minScore < -1 || minScore > 1 ||
      !Number.isFinite(minGap) || minGap <= 0 || minGap > 2) {
    throw new Error("输入合同不合法");
  }
  const byId = new Map(rows.map(row => [row.id, row]));
  const seen = new Set(), candidates = [];
  for (const hit of hits) {
    if (!hit || typeof hit.id !== "string" || seen.has(hit.id) ||
        !Number.isFinite(hit.score) || hit.score < -1 || hit.score > 1) {
      throw new Error("候选格式、分数或重复 ID 不合法");
    }
    seen.add(hit.id);
    const row = byId.get(hit.id);
    if (row?.approved === true && keys.every(k => row[k] === ctx[k])) {
      candidates.push({row, score: hit.score});
    }
  }
  candidates.sort((a, b) => b.score - a.score);
  const [first, second] = candidates;
  if (!first || first.score < minScore ||
      (second && first.score - second.score < minGap)) return null;
  return {id: first.row.id, answer: first.row.answer};
}

const ctx = {build:"1.1", channel:"h5", locale:"zh-CN"};
const rows = [
  {...ctx, id:"old", build:"1.0", approved:true, answer:"通关第 3 关解锁扫荡。"},
  {...ctx, id:"unlock", approved:true, answer:"通关第 5 关解锁扫荡。"},
  {...ctx, id:"ticket", approved:true, answer:"扫荡券来自每日任务。"}
];
const hits = [
  {id:"old", score:0.99}, {id:"unlock", score:0.88}, {id:"ticket", score:0.70}
];
console.log(selectFaq(hits, rows, ctx, 0.80, 0.05));
// { id: "unlock", answer: "通关第 5 关解锁扫荡。" }
```

0.80 与 0.05 只是让规则可演示的参数，不能直接用作 E5 的生产阈值。真实阈值要在带“无答案、歧义问题”的开发集上选择，再在保留集验收。只有一个候选时没有分差证据，本函数只检查最低分；仍可能推荐错误内容。低分或分差不足返回 null，界面应请求补充信息或提供分类浏览。

正文代码在 Node.js 22.16.0 实跑：

| 手工构造输入 | 选择结果 |
| --- | --- |
| 正文三条分数，旧版本最高 | unlock，显示第 5 关条件 |
| 只把全部文档的第一名 old 传入 | null，说明过早截断会漏掉正确版本 |
| unlock=0.88，ticket=0.85 | null，两项过于接近 |
| 当前版本最高分 0.79 | null |
| 唯一命中来自旧版、其他渠道、其他语言或未批准条目 | null |
| 重复 ID、NaN、超出 [-1,1] 的分数 | 抛错，由调用层转入静态帮助 |

**这些分数全部由人构造，只验证选择规则，不代表 E5 的实际输出或准确率。** 检索服务仍须在召回前过滤；这里的补查不能找回已被提前丢掉的正确文档。未知 ID 不进入候选；捕获异常时记录原因，不能将异常算成一次正确回答。
